<div class="section-head"><div><span class="eyebrow">Leaderboard</span><h2><?=e($contest['contest_title']??'Contest rankings')?></h2><p class="muted">Solved problems first, then lower penalty.</p></div><form method="get" class="inline-form"><label class="help" for="contest">Contest</label><select id="contest" name="contest" onchange="this.form.submit()"><?php foreach($contests as $c):?><option value="<?=e($c['contest_id'])?>" <?=($contest['contest_id']??null)==$c['contest_id']?'selected':''?>><?=e($c['contest_title'])?></option><?php endforeach;?></select><noscript><button class="button-small">Load</button></noscript></form></div>
<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Rank</th><th>User</th><th>Institution</th><th>Solved</th><th>Penalty</th><th>Rating</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="<?=user()&&(int)$r['user_id']===(int)user()['user_id']?'current':''?>"><td class="rank-number"><?=e($r['rank_position'])?></td><td><strong><?=e($r['user_name'])?></strong><?=user()&&(int)$r['user_id']===(int)user()['user_id']?'<br><small>That is you!</small>':''?></td><td><?=e($r['institution']??'—')?></td><td><?=e($r['solved_count'])?></td><td><?=e($r['penalty_minutes'])?></td><td><?=e($r['rating'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">No ranked participants yet.</td></tr><?php endif;?></tbody></table></div></section>
